import zipfile,xml.etree.ElementTree as E,pathlib
for p in sorted(pathlib.Path('docs/kiertokirjeet').glob('*.docx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  r=E.fromstring(z.read('word/document.xml'))
  for para in r.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
   print(''.join(para.itertext()))
for p in sorted(pathlib.Path('docs/liitteet').glob('*.xlsx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  ss=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   ss=[''.join(si.itertext()) for si in E.fromstring(z.read('xl/sharedStrings.xml'))]
  for name in z.namelist():
   if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'):
    print(name)
    r=E.fromstring(z.read(name)); ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    for row in r.findall('.//s:row',ns):
     cells=[]
     for c in row:
      v=c.find('s:v',ns)
      val=v.text if v is not None else ''.join(c.find('s:is',ns).itertext()) if c.find('s:is',ns) is not None else ''
      if c.get('t')=='s':val=ss[int(val)]
      cells.append(c.get('r')+'='+val)
     print(' | '.join(cells))
